sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({api, event, helpers, imports}) {
    /**
     * Handles CSR validity period selection change event.
     * 
     * Updates the renew_payload state with the newly selected validity period
     * while preserving existing payload properties.
     * 
     * @param {Object} event - Event object containing the field value
     * @param {string|number} event.payload.fieldValue - The selected validity period
     */

    const selection = event.payload.fieldValue;

    // Immutably update state by spreading existing payload and overwriting validity period
    api.setState('renew_payload', {
        ...api.state.renew_payload,
        csr_validity_period: selection
    });
}
